/// <summary>
/// designed from AVA
/// </summary>
class AVACalcSalesQuotationLine    extends SysOperationServiceController
{
    SalesQuotationLine      salesQuotationLine;


}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void updateQuotationLineFields(boolean   _updateCalcMark = true)
{

    if (_updateCalcMark && salesQuotationLine.SalesPrice != salesQuotationLine.AVAGetMasterSalesPrice())
    {
        salesQuotationLine.KCS_CalcMark = '';
    }
    if (salesQuotationLine.SalesPrice != 0 )
    {
        salesQuotationLine.KCS_LimitPricePuffer =  (1 - (salesQuotationLine.KCS_LimitPrice / salesQuotationLine.SalesPrice))*100;
    }
    else
    {
        salesQuotationLine.KCS_LimitPricePuffer = 0;
    }

    salesQuotationLine.LineAmount = salesQuotationLine.calcLineAmountForced();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_quotationId">_quotationId</param>
public void updateLVPostion(QuotationId     _quotationId)
{
    SalesQuotationLine      localSalesQuotationLine;

    while select localSalesQuotationLine
        where localSalesQuotationLine.QuotationId == _quotationId
    {
        localSalesQuotationLine.AVASetLVPrices(localSalesQuotationLine);
    }

    this.getFinishInfo();

}

/// <summary>
/// designed from AVA
/// </summary>
public void getFinishInfo()
{
    info("@NDX:NXACalcProcessFinish");
}
